application.css:
* { box-sizing: border-box; }

:root {
  color: #172033;
  background: #eef2f7;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body { margin: 0; }

.quiz-shell {
  width: min(100% - 2rem,  Fiftyrem);
  max-width: 50rem;
  margin: 0 auto;
  padding: 2.5rem 0;
}

.page-header, .result, .question {
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: .75rem;
  padding: 1.5rem;
}

.page-header { margin-bottom: 1rem; }
.eyebrow { color: #155e75; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; margin: 0 0 .25rem; font-size: .8rem; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0 0 .75rem; font-size: clamp(1.8rem, 5vw, 2.6rem); }
h2 { font-size: 1.15rem; margin: 0 0 1rem; }
.page-header p:last-child { margin-bottom: 0; }

.question { margin-bottom: 1rem; }
fieldset { border: 0; margin: 0; padding: 0; }
.option {
  display: flex;
  align-items: center;
  gap: .7rem;
  border: 1px solid #94a3b8;
  border-radius: .5rem;
  margin-top: .65rem;
  padding: .8rem;
  cursor: pointer;
}
.option:hover { background: #f0f9ff; border-color: #0369a1; }
.option:has(input:checked) { background: #e0f2fe; border-color: #0369a1; }
input { accent-color: #0369a1; width: 1.1rem; height: 1.1rem; }

button {
  background: #075985;
  border: 0;
  border-radius: .5rem;
  color: #fff;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
  padding: .8rem 1.2rem;
}
button:hover { background: #0c4a6e; }
button:focus-visible, input:focus-visible, .option:has(input:focus-visible) { outline: 3px solid #f59e0b; outline-offset: 3px; }
.actions { margin: 1.25rem 0; }
.status, .error { color: #b42318; font-weight: 600; }
.status { min-height: 1.5em; margin: .75rem 0 0; }
.error { margin: .65rem 0 0; font-size: .95rem; }
.result { margin-top: 1rem; }
.result h2 { margin-bottom: .5rem; }
.score { color: #155e75; font-size: 1.25rem; font-weight: 700; margin: 0; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

@media (max-width: 40rem) {
  .quiz-shell { width: min(100% - 1rem, 50rem); padding: 1rem 0; }
  .page-header, .result, .question { padding: 1.1rem; }
}

application.javascript:
const form = document.querySelector('#quiz-form');
const questions = [...document.querySelectorAll('[data-testid="quiz-question"]')];
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const scoreValue = document.querySelector('#score-value');
const formMessage = document.querySelector('#form-message');

const correctAnswers = ['mars', 'pacific', 'six'];

function getSelectedValue(questionIndex) {
  const selected = document.querySelector(`input[name="question-${questionIndex + 1}"]:checked`);
  return selected ? selected.value : null;
}

function validateAnswers() {
  let isValid = true;
  questions.forEach((question, index) => {
    const error = question.querySelector('.error');
    const hasAnswer = Boolean(getSelectedValue(index));
    error.hidden = hasAnswer;
    if (!hasAnswer) isValid = false;
  });
  return isValid;
}

function calculateScore() {
  return correctAnswers.reduce((score, answer, index) => {
    return score + (getSelectedValue(index) === answer ? 1 : 0);
  }, 0);
}

function showScore(score) {
  scoreValue.textContent = String(score);
  scoreElement.dataset.score = String(score);
  scoreElement.hidden = false;
}

function handleSubmit(event) {
  event.preventDefault();
  formMessage.textContent = '';
  if (!validateAnswers()) {
    formMessage.textContent = 'Please answer all three questions.';
    const firstError = questions.find((question, index) => !getSelectedValue(index));
    if (firstError) firstError.querySelector('input').focus();
    return;
  }
  showScore(calculateScore());
  formMessage.textContent = 'Quiz submitted.';
}

form.addEventListener('submit', handleSubmit);
